#[allow(clippy::too_many_arguments)]
pub fn dump(hdev: [f64; 3], ht: [f64; 3], b: [f64; 3], k: f64, m_max: f64) -> [f64; 3] {
    let mut m: [f64; 3] = [0.0; 3];
    let mut bs: f64 = rt::dot(b, b);
    if (bs < 1.0e-18) {
        m = [0.0; 3];
    } else {
        m = crate::alg::control::sat_dipole(rt::vscale(rt::cross(rt::vsub(hdev, ht), b), (k / bs)), m_max);
    }
    m
}

